#!/usr/bin/env node
/**
 * Cross-language test for the JavaScript port of the ideology generator.
 *
 * This test verifies that generator.js produces identical behavior to the
 * Python lambda_function.py Generator class by:
 *
 * 1. Comparing CSV parsing output (word lists) against Python's parsed results
 * 2. Testing weighted_choice with known random values
 * 3. Replaying the exact random sequence recorded from Python and verifying
 *    identical ideology output
 *
 * Run: node test_generator.js
 * Prerequisites: test_fixtures.json (generated by test_generate_fixtures.py)
 */

const fs = require('fs');
const path = require('path');
const { Generator } = require('./generator.js');

// --- Test infrastructure ---
let totalTests = 0;
let passedTests = 0;
let failedTests = 0;

function assert(condition, message) {
    totalTests++;
    if (condition) {
        passedTests++;
    } else {
        failedTests++;
        console.error(`  FAIL: ${message}`);
    }
}

function assertEqual(actual, expected, message) {
    totalTests++;
    if (actual === expected) {
        passedTests++;
    } else {
        failedTests++;
        console.error(`  FAIL: ${message}`);
        console.error(`    expected: ${JSON.stringify(expected)}`);
        console.error(`    actual:   ${JSON.stringify(actual)}`);
    }
}

function assertDeepEqual(actual, expected, message) {
    totalTests++;
    const actualStr = JSON.stringify(actual);
    const expectedStr = JSON.stringify(expected);
    if (actualStr === expectedStr) {
        passedTests++;
    } else {
        failedTests++;
        console.error(`  FAIL: ${message}`);
        // Show first difference
        const maxLen = Math.max(actualStr.length, expectedStr.length);
        for (let i = 0; i < maxLen; i++) {
            if (actualStr[i] !== expectedStr[i]) {
                console.error(`    first diff at char ${i}:`);
                const start = Math.max(0, i - 30);
                const end = Math.min(i + 30, maxLen);
                console.error(`    expected: ...${expectedStr.substring(start, end)}...`);
                console.error(`    actual:   ...${actualStr.substring(start, end)}...`);
                break;
            }
        }
    }
}

// --- Load fixtures ---
const fixturesPath = path.join(__dirname, 'test_fixtures.json');
if (!fs.existsSync(fixturesPath)) {
    console.error('test_fixtures.json not found. Run test_generate_fixtures.py first.');
    console.error('  .venv/bin/python3 test_generate_fixtures.py');
    process.exit(1);
}

console.log('Loading test fixtures...');
const fixtures = JSON.parse(fs.readFileSync(fixturesPath, 'utf-8'));

// --- Test 1: CSV Parsing ---
console.log('\n=== Test 1: CSV Parsing ===');

const gen = new Generator(fixtures.csv_text);
gen.getWords();

const wordListChecks = [
    ['descAdjs', 'desc_adjs'],
    ['descAdjsWeights', 'desc_adjs_weights'],
    ['descAdjsHaspWeights', 'desc_adjs_hasp_weights'],
    ['descNouns', 'desc_nouns'],
    ['descNounsWeights', 'desc_nouns_weights'],
    ['descNounsHaspWeights', 'desc_nouns_hasp_weights'],
    ['prefixes', 'prefixes'],
    ['prefixWeights', 'prefix_weights'],
    ['prefixHaspWeights', 'prefix_hasp_weights'],
    ['nouns', 'nouns'],
    ['nounsWeights', 'nouns_weights'],
    ['nounsHaspWeights', 'nouns_hasp_weights'],
    ['adverbs', 'adverbs'],
    ['adverbsWeights', 'adverbs_weights'],
    ['endings', 'endings'],
    ['endingsWeights', 'endings_weights'],
    ['allDescs', 'all_descs'],
    ['allDescsWeights', 'all_descs_weights'],
    ['allDescsHaspWeights', 'all_descs_hasp_weights'],
];

for (const [jsName, pyName] of wordListChecks) {
    const jsVal = gen[jsName];
    const pyVal = fixtures.word_lists[pyName];

    // First check length
    assertEqual(jsVal.length, pyVal.length, `${jsName} length matches ${pyName}`);

    // Then check deep equality
    assertDeepEqual(jsVal, pyVal, `${jsName} content matches ${pyName}`);
}

console.log(`  CSV parsing: ${passedTests} passed, ${failedTests} failed out of ${totalTests}`);


// --- Test 2: weighted_choice ---
console.log('\n=== Test 2: weighted_choice ===');

const prevTotal = totalTests;
const prevFailed = failedTests;

for (const tc of fixtures.weighted_choice_tests) {
    // Mock _random to return the specific value
    gen._random = () => tc.random_value;
    const result = gen.weightedChoice(tc.weights);
    assertEqual(result, tc.expected_index,
        `weightedChoice(${JSON.stringify(tc.weights)}) with random=${tc.random_value} => ${tc.expected_index}`);
}

console.log(`  weighted_choice: ${totalTests - prevTotal} tests, ${failedTests - prevFailed} failed`);


// --- Test 3: titleCase ---
console.log('\n=== Test 3: titleCase ===');

const prevTotal3 = totalTests;
const prevFailed3 = failedTests;

// Python's str.title() behavior
const titleCases = [
    ['hello world', 'Hello World'],
    ['hello-world', 'Hello-World'],
    ["don't stop", "Don'T Stop"],  // Python title() capitalizes after apostrophe
    ['neo-Marxism', 'Neo-Marxism'],
    ['UPPER case', 'Upper Case'],
    ['123abc', '123Abc'],
    ['a', 'A'],
    ['', ''],
    ['multi  space', 'Multi  Space'],
    ["it's a test", "It'S A Test"],
];

for (const [input, expected] of titleCases) {
    const result = Generator.titleCase(input);
    assertEqual(result, expected, `titleCase("${input}") => "${expected}"`);
}

console.log(`  titleCase: ${totalTests - prevTotal3} tests, ${failedTests - prevFailed3} failed`);


// --- Test 4: Full ideology generation with replayed random sequence ---
console.log('\n=== Test 4: Full ideology generation ===');

const prevTotal4 = totalTests;
const prevFailed4 = failedTests;

// Create a fresh generator with the same CSV data
const gen2 = new Generator(fixtures.csv_text);
gen2.getWords();

// Set up random replay: the interleaved_calls array contains the exact sequence
// of random.random() and random.choice() calls from the Python run.
const calls = fixtures.generation.interleaved_calls;
let callIdx = 0;

// We need to distinguish between calls to _random() that come from:
// 1. weightedChoice (which calls _random())
// 2. _choice (which calls _random())
// 3. Direct probability checks (which call _random())
//
// In Python, random.random() and random.choice() use different code paths
// but share the same PRNG state. We recorded them interleaved.
//
// In our JS Generator:
// - weightedChoice calls this._random()
// - _choice calls this._random() via Math.floor(this._random() * arr.length)
// - probability checks call this._random()
//
// So we need to make _random return the right value depending on whether
// it's being called from _choice (which expects a 'choice' call) or
// from a probability check / weightedChoice (which expects a 'random' call).
//
// Strategy: We track which random values were consumed for 'random' type calls
// and which indices were chosen for 'choice' type calls. We override both
// _random and _choice.

gen2._random = function() {
    if (callIdx >= calls.length) {
        throw new Error(`Ran out of recorded random calls at index ${callIdx}`);
    }
    const call = calls[callIdx];
    if (call.type !== 'random') {
        throw new Error(`Expected 'random' call at index ${callIdx} but found '${call.type}'`);
    }
    callIdx++;
    return call.value;
};

// Override _choice to use the recorded choice indices
const origChoice = gen2._choice.bind(gen2);
gen2._choice = function(arr) {
    if (callIdx >= calls.length) {
        throw new Error(`Ran out of recorded calls at index ${callIdx}`);
    }
    const call = calls[callIdx];
    if (call.type !== 'choice') {
        throw new Error(`Expected 'choice' call at index ${callIdx} but found '${call.type}'`);
    }
    if (arr.length !== call.seq_len) {
        throw new Error(`Choice seq_len mismatch at index ${callIdx}: expected ${call.seq_len}, got ${arr.length}`);
    }
    callIdx++;
    return arr[call.index];
};

let generationError = null;
let jsIdeologies = [];
let jsTraces = [];

try {
    const result = gen2.getIdeologies(fixtures.generation.n_ideologies);
    jsIdeologies = result[0];
    jsTraces = result[1];
} catch (e) {
    generationError = e;
    console.error(`  ERROR during generation: ${e.message}`);
}

if (!generationError) {
    assertEqual(callIdx, calls.length, `All ${calls.length} recorded random calls were consumed`);
    assertEqual(jsIdeologies.length, fixtures.generation.ideologies.length,
        `Generated ${fixtures.generation.ideologies.length} ideologies`);

    // Compare each ideology
    let ideologyMismatches = 0;
    for (let i = 0; i < fixtures.generation.ideologies.length; i++) {
        const expected = fixtures.generation.ideologies[i];
        const actual = jsIdeologies[i];
        if (actual !== expected) {
            ideologyMismatches++;
            if (ideologyMismatches <= 5) {
                console.error(`  Ideology ${i} mismatch:`);
                console.error(`    expected: "${expected}"`);
                console.error(`    actual:   "${actual}"`);
            }
        }
    }

    totalTests++;
    if (ideologyMismatches === 0) {
        passedTests++;
        console.log(`  All ${jsIdeologies.length} ideologies match!`);
    } else {
        failedTests++;
        console.error(`  ${ideologyMismatches} ideology mismatches out of ${jsIdeologies.length}`);
    }

    // Compare traces
    let traceMismatches = 0;
    for (let i = 0; i < fixtures.generation.traces.length; i++) {
        const expectedTrace = fixtures.generation.traces[i];
        const actualTrace = jsTraces[i];
        if (JSON.stringify(actualTrace) !== JSON.stringify(expectedTrace)) {
            traceMismatches++;
            if (traceMismatches <= 3) {
                console.error(`  Trace ${i} mismatch:`);
                console.error(`    expected: ${JSON.stringify(expectedTrace)}`);
                console.error(`    actual:   ${JSON.stringify(actualTrace)}`);
            }
        }
    }

    totalTests++;
    if (traceMismatches === 0) {
        passedTests++;
        console.log(`  All ${jsTraces.length} traces match!`);
    } else {
        failedTests++;
        console.error(`  ${traceMismatches} trace mismatches out of ${jsTraces.length}`);
    }
}

console.log(`  Full generation: ${totalTests - prevTotal4} tests, ${failedTests - prevFailed4} failed`);


// --- Test 5: Verify JS Generator works standalone (no mocking) ---
console.log('\n=== Test 5: Standalone generation (smoke test) ===');

const prevTotal5 = totalTests;
const prevFailed5 = failedTests;

const gen3 = new Generator(fixtures.csv_text);
gen3.getWords();

// Reset to real Math.random
gen3._random = Math.random;
gen3._choice = function(arr) {
    const idx = Math.floor(this._random() * arr.length);
    return arr[idx];
};

const [smokeIdeologies] = gen3.getIdeologies(20);
assertEqual(smokeIdeologies.length, 20, 'Generated 20 smoke test ideologies');

for (let i = 0; i < smokeIdeologies.length; i++) {
    assert(typeof smokeIdeologies[i] === 'string' && smokeIdeologies[i].length > 0,
        `Ideology ${i} is non-empty string: "${smokeIdeologies[i]}"`);
}

console.log(`  Smoke test: ${totalTests - prevTotal5} tests, ${failedTests - prevFailed5} failed`);
console.log('  Sample ideologies:');
for (let i = 0; i < 5; i++) {
    console.log(`    ${i}: ${smokeIdeologies[i]}`);
}


// --- Summary ---
console.log('\n========================================');
console.log(`TOTAL: ${totalTests} tests, ${passedTests} passed, ${failedTests} failed`);

if (failedTests > 0) {
    console.log('RESULT: FAIL');
    process.exit(1);
} else {
    console.log('RESULT: PASS');
    process.exit(0);
}
